{
  "explanation": "The matrix [[2, 1], [0, 1]] shears the plane horizontally while stretching the x-direction by 2. The unit square becomes a parallelogram of base 2 and height 1. The determinant equals 2·1 − 1·0 = 2, which is exactly the factor by which areas are scaled — here the unit square’s area 1 becomes area 2.",
  "manimCode": "const matrix = [[2, 1], [0, 1]];
const det = matrix[0][0] * matrix[1][1] - matrix[0][1] * matrix[1][0];

function lerpMat(s) {
  return [
    [1 + s, s],
    [0, 1]
  ];
}

function apply(m, x, y) {
  return [m[0][0] * x + m[0][1] * y, m[1][0] * x + m[1][1] * y];
}

const ax = new Axes({
  xRange: [-3, 5, 1],
  yRange: [-2, 3, 1],
  xLength: 10,
  yLength: 6,
  tips: true
});
ax.setStrokeWidth(1.5);
scene.add(ax);

const title = new Text({ text: 'Matrix [[2, 1], [0, 1]]  —  det = 2', color: WHITE, fontSize: 28 });
title.moveTo([0, 3.5, 0]);
scene.add(title);

let tVal = 0;

function buildGrid(s) {
  const m = lerpMat(s);
  const lines = [];
  for (let i = -2; i <= 4; i++) {
    const p0 = apply(m, i, -1.5);
    const p1 = apply(m, i, 2.5);
    const ln = new Polygon({
      vertices: [ax.c2p(p0[0], p0[1]), ax.c2p(p1[0], p1[1])],
      color: GRAY,
      strokeWidth: 1
    });
    ln.setFillOpacity(0);
    lines.push(ln);
  }
  for (let j = -1; j <= 2; j++) {
    const p0 = apply(m, -2, j);
    const p1 = apply(m, 4, j);
    const ln = new Polygon({
      vertices: [ax.c2p(p0[0], p0[1]), ax.c2p(p1[0], p1[1])],
      color: GRAY,
      strokeWidth: 1
    });
    ln.setFillOpacity(0);
    lines.push(ln);
  }
  return lines;
}

function buildSquare(s, color, opacity) {
  const m = lerpMat(s);
  const corners = [[0, 0], [1, 0], [1, 1], [0, 1]].map(([x, y]) => {
    const p = apply(m, x, y);
    return ax.c2p(p[0], p[1]);
  });
  const poly = new Polygon({ vertices: corners, color: color, strokeWidth: 3 });
  poly.setFill(color, opacity);
  return poly;
}

function buildBasis(s) {
  const m = lerpMat(s);
  const o = ax.c2p(0, 0);
  const iEnd = apply(m, 1, 0);
  const jEnd = apply(m, 0, 1);
  const iArr = new Arrow({ start: o, end: ax.c2p(iEnd[0], iEnd[1]), color: GREEN });
  const jArr = new Arrow({ start: o, end: ax.c2p(jEnd[0], jEnd[1]), color: RED });
  return [iArr, jArr];
}

let gridLines = buildGrid(0);
gridLines.forEach(l => scene.add(l));

const origSquare = buildSquare(0, BLUE_E, 0.15);
origSquare.setStrokeWidth(1);
scene.add(origSquare);

let liveSquare = buildSquare(0, YELLOW, 0.35);
scene.add(liveSquare);

let [iHat, jHat] = buildBasis(0);
scene.add(iHat, jHat);

let iLabel = new Text({ text: 'î', color: GREEN, fontSize: 22 });
iLabel.nextTo(iHat, DOWN);
scene.add(iLabel);

let jLabel = new Text({ text: 'ĵ', color: RED, fontSize: 22 });
jLabel.nextTo(jHat, LEFT);
scene.add(jLabel);

let areaLabel = new Text({ text: 'Area = 1.00   (× det = 1.00)', color: GOLD, fontSize: 24 });
areaLabel.moveTo([0, -3.3, 0]);
scene.add(areaLabel);

const detNote = new MathTex({ latex: '\\det\\begin{pmatrix}2&1\\\\0&1\\end{pmatrix}=2' });
await detNote.waitForRender();
detNote.scale(0.7);
detNote.moveTo([3.8, 2.6, 0]);
scene.add(detNote);

function rebuild(s) {
  gridLines.forEach(l => scene.remove(l));
  gridLines = buildGrid(s);
  gridLines.forEach(l => scene.add(l));

  scene.remove(liveSquare);
  liveSquare = buildSquare(s, YELLOW, 0.35);
  scene.add(liveSquare);

  scene.remove(iHat);
  scene.remove(jHat);
  [iHat, jHat] = buildBasis(s);
  scene.add(iHat, jHat);

  scene.remove(iLabel);
  scene.remove(jLabel);
  iLabel = new Text({ text: 'î', color: GREEN, fontSize: 22 });
  const m = lerpMat(s);
  const iEnd = apply(m, 1, 0);
  const jEnd = apply(m, 0, 1);
  iLabel.moveTo(ax.c2p(iEnd[0], iEnd[1] - 0.35));
  jLabel = new Text({ text: 'ĵ', color: RED, fontSize: 22 });
  jLabel.moveTo(ax.c2p(jEnd[0] - 0.35, jEnd[1]));
  scene.add(iLabel, jLabel);

  const area = 1 + s;
  scene.remove(areaLabel);
  areaLabel = new Text({
    text: 'Area = ' + area.toFixed(2) + '   (× det factor = ' + area.toFixed(2) + ')',
    color: GOLD,
    fontSize: 24
  });
  areaLabel.moveTo([0, -3.3, 0]);
  scene.add(areaLabel);
}

const controls = new Controls(scene, { position: 'bottom-right', width: 280 });
controls.addSlider({
  label: 'Transform t',
  min: 0,
  max: 1,
  value: 0,
  step: 0.01,
  onChange: (v) => {
    tVal = v;
    rebuild(tVal);
  }
});
controls.addButton({
  label: 'Play full transform',
  onClick: async () => {
    const steps = 40;
    for (let i = 0; i <= steps; i++) {
      tVal = i / steps;
      rebuild(tVal);
      await scene.wait(0.03);
    }
  }
});
controls.addButton({
  label: 'Reset',
  onClick: () => {
    tVal = 0;
    rebuild(0);
  }
});

await scene.wait(999999);"
